      { id=533, name="Kael'thas Sunstrider", order=4,
        uiMapID=348, x=0.0861, y=0.502, rootSection=5166,
        desc="Once a true champion to the blood elf people, and a defender of the race's ancient heritage, Kael'thas Sunstrider has fallen prey to the dark influences of the demon Kil'jaeden while sojourning in Outland. At the bidding of his new master, the wayward prince returned to Azeroth and seized the Sunwell, hoping to use the fount as a means to open a doorway for the demon to this new and verdant world. Kael'thas is a brilliant tactician, a powerful warrior, and his veins burn with limitless fel magic.",
        creatures = { {display=22906, file=607669, name="Kael'thas Sunstrider"} },
