  { id=250, name="Mana-Tombs", isRaid=false, minLevel=60,
    mapID=557, loreFDID=608232, bgFDID=608154, buttonFDID=608193,
    desc="The original exiles on Draenor found death to be an unsettling and unfortunate consequence of life, and so the draenei hid their dead away in the subterranean grave-city of Auchindoun, a labyrinthine marvel located beneath the forests of Terokkar.",
    encounters = {
