        loot = { {id=27890,pct=10.8,q=3,diff=6,name="Wand of the Netherwing"}, {id=27892,pct=16.3,q=3,diff=6,name="Cloak of the Inciter"}, {id=27891,pct=10.9,q=3,diff=6,name="Adamantine Figurine"}, {id=27893,pct=13.3,q=3,diff=6,name="Ornate Leggings of the Venerated"}, {id=28134,pct=10.5,q=3,diff=6,name="Brooch of Hightened Potential"} },
