      { id=546, name="Grandmaster Vorpil", order=3,
        uiMapID=260, x=0.5314, y=0.541, rootSection=5266,
        desc="In the early days of the Horde, Grandmaster Vorpil convinced the orc warlock Gul'dan to allow him to investigate the mysteries of Auchindoun, secretly desiring to harness the energy of the frighteningly powerful cosmic essences that permeated the area.",
        creatures = { {display=18535, file=607625, name="Grandmaster Vorpil"} },
