      { id=547, name="Murmur", order=4,
        uiMapID=260, x=0.8087, y=0.3914, rootSection=5272,
        desc="\"In the beginning\"... \"So far away\"... such phrases cannot begin to describe this elemental's origin. Its existence heralds pure destruction. Worlds shatter and the pieces scatter at its whim. Only the truly mad would think to summon it. Perhaps there is yet time to banish Murmur before it fully enters Outland.",
        creatures = { {display=18839, file=607720, name="Murmur"} },
        loot = { {id=27912,pct=13.6,q=3,diff=6,name="Harness of the Deep Currents"}, {id=27902,pct=12.3,q=3,diff=6,name="Silent Slippers of Meditation"}, {id=27910,pct=12.5,q=3,diff=6,name="Silvermoon Crest Shield"}, {id=27913,pct=9.7,q=3,diff=6,name="Whispering Blade of Slaying"}, {id=29353,pct=10.7,q=4,diff=6,name="Shockwave Truncheon"}, {id=28232,pct=10.5,q=3,diff=6,name="Robe of Oblivion"}, {id=29357,pct=10.0,q=4,diff=6,name="Master Thief's Gloves"}, {id=27803,pct=9.5,q=3,diff=6,name="Shoulderguards of the Bold"}, {id=27905,pct=9.3,q=3,diff=6,name="Greatsword of Horrid Dreams"}, {id=27903,pct=11.2,q=3,diff=6,name="Sonic Spear"}, {id=30532,pct=11.9,q=4,diff=6,name="Kirin Tor Master's Trousers"}, {id=28230,pct=11.5,q=3,diff=6,name="Hallowed Garments"}, {id=29261,pct=3.6,q=4,diff=6,name="Girdle of Ferocity"}, {id=27778,pct=12.3,q=3,diff=6,name="Spaulders of Oblivion"} },
