          { id=5272, title="Sonic Boom", parent=0, child=0, sib=5273, order=1, spell=0, icon="Interface\\icons\\spell_nature_astralrecal", flags=0, cdisp=0,
            body="Murmur releases a massive burst of sonic energy that blasts players within $33666A1 yards with Nature damage, then inflicts additional Nature damage every $33666t2 seconds for $33666d.  While affected by Sonic Boom, movement speed is reduced by $33666s3%." },
