  { id=258, name="The Mechanar", isRaid=false, minLevel=60,
    mapID=554, loreFDID=608257, bgFDID=608179, buttonFDID=608218,
    desc="The mighty Tempest Keep was created by the enigmatic naaru: sentient beings of pure energy and the sworn enemies of the Burning Legion. In addition to serving as a base of operations for the naaru, the structure itself possesses the technology to teleport through alternate dimensions, traveling from one location to another in the blink of an eye.",
    encounters = {
      { id=563, name="Mechano-Lord Capacitus", order=1,
        uiMapID=267, x=0.5137, y=0.3156, rootSection=5479,
        desc="It takes a tremendous amount of skill and precision to harvest the power of the naaru's manacells. These talents can easily be turned upon any intruders.",
        creatures = { {display=19162, file=607712, name="Mechano-Lord Capacitus"} },
        loot = { {id=28256,pct=14.8,q=3,diff=6,name="Thoriumweave Cloak"}, {id=28257,pct=14.4,q=3,diff=6,name="Hammer of the Penitent"}, {id=28253,pct=17.7,q=3,diff=6,name="Plasma Rat's Hyper-Scythe"}, {id=28254,pct=16.8,q=3,diff=6,name="Warp Engineer's Prismatic Chain"}, {id=28255,pct=17.0,q=3,diff=6,name="Lunar-Claw Pauldrons"} },
        sections = {
          { id=5479, title="Head Crack", parent=0, child=0, sib=5480, order=1, spell=0, icon="Interface\\icons\\ability_thunderbolt", flags=0, cdisp=0,
            body="Mechano-Lord Capacitus reduces a player's Stamina by $35161s1 for $35161d." },
          { id=5480, title="Nether Charges", parent=0, child=0, sib=5481, order=2, spell=0, icon=465875, flags=0, cdisp=0,
            body="Mechano-Lord Capacitus frequently summons Nether Charges which detonate after 15 seconds, inflicting $35152s1 Arcane damage to all players within $35152A1 yards." },
          { id=5481, title="Reflective Magic Shield", parent=0, child=0, sib=5482, order=3, spell=0, icon="Interface\\icons\\spell_frost_frostarmor02", flags=2, cdisp=0,
            body="Mechano-Lord Capacitus surrounds himself in a protective shield that reflects $35158s1% of all harmful spells for $35158d." },
          { id=5482, title="Reflective Damage Shield", parent=0, child=0, sib=5483, order=4, spell=0, icon="Interface\\icons\\spell_shadow_antishadow", flags=2, cdisp=0,
            body="Mechano-Lord Capacitus surrounds himself with a protective shield that inflicts $35159s1 Arcane damage to melee attackers when hit." },
          { id=5483, title="Polarity Shift", parent=0, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_chargepositive", flags=2, cdisp=0,
            body="Mechano-Lord Capacitus charges all players with energy, shifting their polarity to either positive or negative. Damage done by the player will be increased for each similarly charged player that is within $39093A1 yards and they will inflict Nature damage to all oppositely charged players within $39093A1 yards every $39091t2 seconds." },
        },
      },
      { id=564, name="Nethermancer Sepethrea", order=2,
        uiMapID=268, x=0.4781, y=0.2029, rootSection=5484,
        desc="Thanks to her skills at quickly summoning creatures to destroy any enemies, Sepethrea was chosen as an apprentice to Pathaleon the Calculator, the blood elf in charge of the Mechanar.",
        creatures = { {display=19166, file=607725, name="Nethermancer Sepethrea"} },
        loot = { {id=28259,pct=18.1,q=3,diff=6,name="Cosmic Lifeband"}, {id=28260,pct=15.6,q=3,diff=6,name="Manual of the Nethermancer"}, {id=28262,pct=15.4,q=3,diff=6,name="Jade-Skull Breastplate"}, {id=28263,pct=15.6,q=3,diff=6,name="Stellaris"}, {id=28275,pct=14.8,q=3,diff=6,name="Beast Lord Helm"}, {id=28202,pct=11.9,q=3,diff=6,name="Moonglade Robe"} },
        sections = {
          { id=5484, title="Dragon's Breath", parent=0, child=0, sib=5485, order=1, spell=0, icon="Interface\\icons\\inv_misc_head_dragon_01", flags=0, cdisp=0,
            body="Nethermancer Sepethrea inflicts Fire damage to all players in front of her, disorienting them for $35250d." },
          { id=5485, title="Frost Attack", parent=0, child=0, sib=5486, order=2, spell=0, icon="Interface\\icons\\spell_frost_frostbrand", flags=0, cdisp=0,
            body="Nethermancer Sepethrea's weapon is enchanted with Frost, giving her successful melee attacks a chance to inflict Frost damage and slow the movement speed of her target for $35263d." },
          { id=5486, title="Arcane Blast", parent=0, child=0, sib=5487, order=3, spell=0, icon="Interface\\icons\\spell_arcane_blast", flags=0, cdisp=0,
            body="Nethermancer Sepethrea blasts a player with magic, inflicting Arcane damage and knocking them back, reducing their total threat by half." },
          { id=5487, title="Raging Flames", parent=0, child=5488, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=5488,
            body="Nethermancer Sepethrea summons 2 Raging Flames when she enters combat. Raging Flames ignore threat and pursue a player for a short time." },
          { id=5488, title="Inferno", parent=5487, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_fire_incinerate", flags=1, cdisp=0,
            body="Raging Flames surround themselves with an inferno for $39346d, inflicting Fire damage to all players within $35283A1 yards every second. While aflame, Raging Flames are unable to move or use abilities. When the inferno ends, Raging Flames choose a new target to pursue." },
        },
      },
      { id=565, name="Pathaleon the Calculator", order=3,
        uiMapID=268, x=0.2719, y=0.6107, rootSection=5489,
        desc="Following the Sunwell's defilement, the vainglorious arcanist Pathaleon saw an opportunity to gain renown by aiding Kael'thas in finding a cure for his race's addiction to magic. This single-minded quest led him to join the blood elf prince on Outland and oversee his disastrous experiments. Most recently, Pathaleon has begun harnessing the Tempest Keep's otherworldly technologies in pursuit of fame and power.",
        creatures = { {display=20033, file=607739, name="Pathaleon the Calculator"} },
