  { id=259, name="The Shattered Halls", isRaid=false, minLevel=60,
    mapID=540, loreFDID=608246, bgFDID=608168, buttonFDID=608207,
    desc="At the heart of Outland's barren Hellfire Peninsula stands Hellfire Citadel, a nearly impenetrable bastion that served as the Horde's base of operations throughout the First and Second Wars.",
    encounters = {
      { id=566, name="Grand Warlock Nethekurse", order=1,
        uiMapID=246, x=0.3333, y=0.6209, rootSection=5497,
        desc="Nethekurse, once a shaman of the Shadowmoon clan, abandoned his reverence for the elements to master the art of wielding fel magic. The demonic energies at his command have left him a husk who finds delight only in torturing young fel orcs to test the limits of their mental and physical strength.",
        creatures = { {display=16628, file=607624, name="Grand Warlock Nethekurse"} },
        loot = { {id=27529,pct=10.4,q=3,diff=6,name="Figurine of the Colossus"}, {id=27519,pct=17.4,q=3,diff=6,name="Cloak of Malice"}, {id=27521,pct=16.5,q=3,diff=6,name="Telaari Hunting Girdle"}, {id=27520,pct=16.5,q=3,diff=6,name="Greathelm of the Unbreakable"}, {id=27534,pct=13.0,q=3,diff=6,name="Hortus' Seal of Brilliance"}, {id=27517,pct=17.5,q=3,diff=6,name="Bands of Nethekurse"} },
        sections = {
