            body="Grand Warlock Nethekurse inflicts Shadow damage to a player and their nearest allies, affecting up to $30495x1 targets." },
          { id=29956, title="Shadow Slam", parent=0, child=0, sib=5498, order=2, spell=0, icon="Interface\\icons\\ability_warrior_cleave", flags=2, cdisp=0,
            body="Grand Warlock Nethekurse inflicts Shadow damage all players in front of him." },
          { id=5498, title="Death Coil", parent=0, child=0, sib=5499, order=3, spell=0, icon="Interface\\icons\\spell_shadow_deathcoil", flags=0, cdisp=0,
            body="Grand Warlock Nethekurse causes a player to cower in horror for $30500d, inflicting $30500s1 Shadow damage. Nethekurse gains 100% of the damage caused in health." },
          { id=5499, title="Lesser Shadow Fissure", parent=0, child=0, sib=5500, order=4, spell=0, icon="Interface\\icons\\inv_enchant_voidsphere", flags=0, cdisp=0,
            body="Grand Warlock Nethekurse creates a fissure of Consumption under a player, inflicting $30498s1 Shadow damage every $30498t1 sec while they are inside of the fissure." },
          { id=5500, title="Dark Spin", parent=0, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_shadow_shadowmend", flags=0, cdisp=0,
