        },
      },
      { id=728, name="Blood Guard Porung", order=2,
        uiMapID=246, x=0.2968, y=0.1466, rootSection=6662,
        desc="During the bloody siege of Shattrath, Porung stormed an enclave of draenei paladins who had barricaded themselves within a corner of the city. He single-handedly slaughtered the defenders, but suffered a grave injury that left him incapable of following the Horde when it later stormed Azeroth. Now recovered, Porung serves Warchief Kargath Bladefist in Hellfire Citadel, hoping to make up for the glorious battles he has missed and write his name in orcish history with the blood of his enemies.",
        creatures = { {display=17725, file=607556, name="Blood Guard Porung"} },
        loot = { {id=27536,pct=12.6,q=3,diff=6,name="Hallowed Handwraps"}, {id=30707,pct=10.4,q=3,diff=6,name="Nimble-foot Treads"}, {id=30705,pct=21.9,q=3,diff=6,name="Spaulders of Slaughter"}, {id=30710,pct=10.4,q=3,diff=6,name="Blood Guard's Necklace of Ferocity"}, {id=30709,pct=14.6,q=3,diff=6,name="Pantaloons of Flaming Wrath"}, {id=30708,pct=12.5,q=3,diff=6,name="Belt of Flowing Thought"}, {id=27474,pct=10.7,q=3,diff=6,name="Beast Lord Handguards"} },
