            body="Blood Guard Porung is only available in Heroic Difficulty." },
          { id=6216, title="Cleave", parent=0, child=0, sib=29957, order=2, spell=0, icon="Interface\\icons\\ability_warrior_cleave", flags=2, cdisp=0,
            body="Blood Guard Porung cleaves, inflicting Physical damage to a player and their closest allies." },
          { id=29957, title="Bloodthirst", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_bloodlust", flags=2, cdisp=0,
            body="Blood Guard Porung thirsts for blood, inflicting Physical damage and causing his next $35948n succesful melee attacks to restore $35947s1 health." },
        },
      },
      { id=568, name="Warbringer O'mrogg", order=3,
        uiMapID=246, x=0.5423, y=0.3422, rootSection=5893,
        desc="The ruthless and cunning ogre O'mrogg is considered one of the Fel Horde's deadliest members. But this feared brute has a problem. The ogre's two heads have always struggled to agree on even the simplest matters. Two years ago, O'mrogg began a twelve-step plan to develop a synergy between his warring personalities. His heads have yet to decide on which step to start with.",
        creatures = { {display=18031, file=607811, name="Warbringer O'mrogg"} },
        loot = { {id=29254,pct=0,q=4,diff=6,name="Boots of the Righteous Path"}, {id=27526,pct=17.3,q=3,diff=6,name="Skyfire Hawk-Bow"}, {id=29263,pct=0.3,q=4,diff=6,name="Forestheart Bracers"}, {id=27868,pct=15.3,q=3,diff=6,name="Runesong Dagger"}, {id=27524,pct=17.9,q=3,diff=6,name="Firemaul of Destruction"}, {id=27525,pct=18.3,q=3,diff=6,name="Jeweled Boots of Sanctification"}, {id=27522,pct=25.8,q=3,diff=6,name="World's End Bracers"} },
        sections = {
          { id=5893, title="Thunderclap", parent=0, child=0, sib=5894, order=1, spell=0, icon="Interface\\icons\\spell_nature_thunderclap", flags=0, cdisp=0,
