  { id=260, name="The Slave Pens", isRaid=false, minLevel=60,
    mapID=547, loreFDID=608238, bgFDID=608160, buttonFDID=608199,
    desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
    encounters = {
      { id=570, name="Mennu the Betrayer", order=1,
        uiMapID=265, x=0.4904, y=0.2705, rootSection=5902,
        desc="Mennu is one of the Broken, draenei twisted and deformed by demonic energies unleashed by the orcs. When the naga invaded Zangarmarsh, many of these tragic beings desperately attempted to escape the region. Mennu, however, chose a different path to freedom. In exchange for his own life, he betrayed his fellow Broken to the serpentine invaders and agreed to lord over his kin as a slave driver.",
        creatures = { {display=17728, file=607715, name="Mennu the Betrayer"} },
        loot = { {id=24356,pct=12.5,q=3,diff=6,name="Wastewalker Shiv"}, {id=24357,pct=11.9,q=3,diff=6,name="Vest of Living Lightning"}, {id=27541,pct=12.8,q=3,diff=6,name="Archery Belt of the Broken"}, {id=27542,pct=16.5,q=3,diff=6,name="Cord of Belief"}, {id=24359,pct=10.2,q=3,diff=6,name="Princely Reign Leggings"}, {id=27543,pct=20.0,q=3,diff=6,name="Starlight Dagger"}, {id=24360,pct=11.1,q=3,diff=6,name="Tracker's Belt"}, {id=27545,pct=8.5,q=3,diff=6,name="Mennu's Scaled Leggings"}, {id=24361,pct=11.1,q=3,diff=6,name="Spellfire Longsword"}, {id=27546,pct=13.8,q=3,diff=6,name="Traitor's Noose"} },
        sections = {
