            body="Mennu the Betrayer blasts a player with lightning, inflicting Nature damage." },
          { id=5903, title="Tainted Earthgrab Totem", parent=0, child=0, sib=5904, order=2, spell=0, icon="Interface\\icons\\spell_nature_naturetouchdecay", flags=0, cdisp=0,
            body="Mennu the Betrayer summons an Earthgrab Totem that lasts $31981d. and periodically immobilizes nearby players." },
          { id=5904, title="Tainted Stoneskin Totem", parent=0, child=0, sib=5905, order=3, spell=0, icon="Interface\\icons\\spell_nature_stoneskintotem", flags=0, cdisp=0,
            body="Mennu the Betrayer summons a Stoneskin Totem that lasts $31985d and reduces his melee damage taken by $31986s1%." },
