            body="Mennu the Betrayer summons a Nova Totem that inflicts Fire damage to all nearby players after 18 seconds or when it is destroyed." },
        },
      },
      { id=571, name="Rokmar the Crackler", order=2,
        uiMapID=265, x=0.5806, y=0.4057, rootSection=5907,
        desc="Following Draenor's destruction, Rokmar fled into the depths of Zangarmarsh. The energies that had torn the world apart enveloped the behemoth, bolstering its strength and size at the price of constant agony. The naga were awed by Rokmar's ferocity when they first arrived in the region. Rather than kill the beast, they enslaved it and used the creature to subjugate much of Zangarmarsh's indigenous life.",
        creatures = { {display=17729, file=607759, name="Rokmar the Crackler"} },
        loot = { {id=24376,pct=11.4,q=3,diff=6,name="Runed Fungalcap"}, {id=24378,pct=9.7,q=3,diff=6,name="Coilfang Hammer of Renewal"}, {id=24379,pct=10.1,q=3,diff=6,name="Bogstrok Scale Cloak"}, {id=27547,pct=14.8,q=3,diff=6,name="Coldwhisper Cord"}, {id=28124,pct=9.0,q=3,diff=6,name="Liar's Cord"}, {id=27548,pct=14.8,q=3,diff=6,name="Girdle of Many Blessings"}, {id=24380,pct=10.3,q=3,diff=6,name="Calming Spore Reed"}, {id=24381,pct=10.1,q=3,diff=6,name="Coilfang Needler"}, {id=27549,pct=9.8,q=3,diff=6,name="Wavefury Boots"}, {id=27550,pct=11.5,q=3,diff=6,name="Ironscale War Cloak"}, {id=27551,pct=16.2,q=3,diff=6,name="Skeletal Necklace of Battlerage"} },
        sections = {
          { id=5907, title="Grievous Wound", parent=0, child=0, sib=5908, order=1, spell=0, icon="Interface\\icons\\ability_backstab", flags=0, cdisp=0,
            body="Rokmar the Crackler viciously attacks a player, inflicting $31956s1 Physical damage every $31956t1 seconds until fully healed." },
          { id=5908, title="Ensnaring Moss", parent=0, child=0, sib=5909, order=2, spell=0, icon="Interface\\icons\\spell_nature_regenerate", flags=0, cdisp=0,
            body="Rokmar the Crackler encumbers a player with moss, slowing their melee and casting speed by $31948s1%." },
          { id=5909, title="Water Spit", parent=0, child=0, sib=5910, order=3, spell=0, icon="Interface\\icons\\spell_frost_frostbolt", flags=0, cdisp=0,
            body="Rokmar the Crackler hurls watery bolts of water at all players within $35008A1 yards, inflicting $35008s1 Frost damage." },
          { id=5910, title="Frenzy", parent=0, child=0, sib=0, order=4, spell=0, icon="Interface\\icons\\spell_shadow_unholyfrenzy", flags=0, cdisp=0,
            body="Rokmar the Crackler enters a Frenzy, increasing Physical damage by $34970s1 and attack speed by $34970s2%." },
        },
