      { id=572, name="Quagmirran", order=3,
        uiMapID=265, x=0.821, y=0.7684, rootSection=5977,
        desc="Quagmirran was once a ruler of Zangarmarsh's immense fungal giants. He was captured by the naga while wandering the region's serpentine caverns and subjected to excruciating torture. Now this broken being serves his overlords without question, silencing all who oppose the will of Lady Vashj.",
        creatures = { {display=18224, file=607750, name="Quagmirran"} },
        loot = { {id=27712,pct=0,q=3,diff=6,name="Shackles of Quagmirran"}, {id=27713,pct=10.7,q=3,diff=6,name="Pauldrons of Desolation"}, {id=27714,pct=10.9,q=3,diff=6,name="Swamplight Lantern"}, {id=27683,pct=7.9,q=3,diff=6,name="Quagmirran's Eye"}, {id=29349,pct=1.5,q=4,diff=6,name="Adamantine Chain of the Unbroken"}, {id=24362,pct=10.6,q=3,diff=6,name="Spore-Soaked Vaneer"}, {id=30538,pct=8.9,q=4,diff=6,name="Midnight Legguards"}, {id=24363,pct=9.5,q=3,diff=6,name="Unscarred Breastplate"}, {id=24364,pct=10.0,q=3,diff=6,name="Azureplate Greaves"}, {id=24365,pct=10.9,q=3,diff=6,name="Deft Handguards"}, {id=32078,pct=0,q=4,diff=6,name="Pauldrons of Wild Magic"}, {id=24366,pct=11.7,q=3,diff=6,name="Scorpid-Sting Mantle"}, {id=28337,pct=8.7,q=3,diff=6,name="Breastplate of Righteous Fury"}, {id=27796,pct=5.2,q=3,diff=6,name="Mana-Etched Spaulders"}, {id=27672,pct=7.6,q=3,diff=6,name="Girdle of the Immovable"}, {id=27800,pct=13.8,q=3,diff=6,name="Earthsoul Britches"}, {id=27673,pct=0,q=3,diff=6,name="Phosphorescent Blade"}, {id=29242,pct=10.0,q=4,diff=6,name="Boots of Blasphemy"}, {id=27740,pct=12.2,q=3,diff=6,name="Band of Ursol"}, {id=27741,pct=9.8,q=3,diff=6,name="Bleeding Hollow Warhammer"}, {id=27742,pct=12.0,q=3,diff=6,name="Mage-Fury Girdle"} },
