  { id=261, name="The Steamvault", isRaid=false, minLevel=60,
    mapID=545, loreFDID=608238, bgFDID=608160, buttonFDID=608199,
    desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
    encounters = {
      { id=573, name="Hydromancer Thespia", order=1,
        uiMapID=263, x=0.5423, y=0.1373, rootSection=5982,
        desc="At the height of the night elf empire, the Highborne Thespia delighted in art and music. Her love of these things vanished during the Great Sundering, when she and many of her kin were sucked into Azeroth's deeps and transformed into hateful naga. In the millennia that followed, Thespia remained a close confidant of her childhood friend, Lady Vashj. Without hesitation, she journeyed with her comrade to Zangarmarsh and vowed to oversee the naga's quest to drain the region's water supply.",
        creatures = { {display=11268, file=607651, name="Hydromancer Thespia"} },
        loot = { {id=27784,pct=16.7,q=3,diff=6,name="Scintillating Coral Band"}, {id=27508,pct=17.1,q=3,diff=6,name="Incanter's Gloves"}, {id=27789,pct=14.3,q=3,diff=6,name="Cloak of Whispering Shells"}, {id=27783,pct=18.7,q=3,diff=6,name="Moonrage Girdle"}, {id=27806,pct=14.8,q=3,diff=6,name="Fathomheart Gauntlets"}, {id=27475,pct=10.1,q=3,diff=6,name="Gauntlets of the Bold"} },
        sections = {
          { id=5982, title="Enveloping Winds", parent=0, child=0, sib=5983, order=1, spell=0, icon="Interface\\icons\\spell_nature_cyclone", flags=0, cdisp=0,
            body="Hydromancer Thespia surrounds a player with a cyclone, stunning them for $31718d." },
          { id=5983, title="Lightning Cloud", parent=0, child=0, sib=5984, order=2, spell=0, icon="Interface\\icons\\spell_nature_callstorm", flags=0, cdisp=0,
            body="Hydromancer Thespia creates a cloud of lightning at a player's location that lasts for $25033d., inflicting $25033s1 Nature damage every $25033t2 seconds." },
          { id=5984, title="Lung Burst", parent=0, child=0, sib=5985, order=3, spell=0, icon="Interface\\icons\\ability_suffocate", flags=0, cdisp=0,
            body="Hydromancer Thespia compresses a player's lungs, inflicting $31481s1 Physical damage every $31481t1 sec for $31481d." },
          { id=5985, title="Coilfang Water Elemental", parent=0, child=5986, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=5564,
            body="Two Coilfang Water Elementals defend Hydromancer Thespia in battle." },
          { id=5986, title="Water Bolt Volley", parent=5985, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_frost_frostbolt", flags=0, cdisp=0,
            body="Coilfang Water Elementals hurl a volley of watery bolts at all nearby players, inflicting $34449s1 Frost damage." },
        },
      },
      { id=574, name="Mekgineer Steamrigger", order=2,
        uiMapID=263, x=0.3415, y=0.8197, rootSection=5996,
        desc="The irradiation of Gnomeregan transformed many of the city's survivors into leper gnomes. Among these victims was the brilliant Mekgineer Steamrigger. Although he escaped Gnomeregan and retained his intellect, whatever ethics and compassion he had once possessed were gone. He wandered Azeroth, selling his knowledge to a number of unscrupulous groups such as the Bloodsail Buccaneers. Recently, the naga hired Steamrigger to operate the intricate machinery in Zangarmarsh's Steamvault.",
        creatures = { {display=18638, file=607713, name="Mekgineer Steamrigger"} },
        loot = { {id=27792,pct=14.5,q=3,diff=6,name="Steam-Hinge Chain of Valor"}, {id=27793,pct=16.9,q=3,diff=6,name="Earth Mantle Handwraps"}, {id=27794,pct=15.9,q=3,diff=6,name="Recoilless Rocket Ripper X-54"}, {id=27790,pct=16.6,q=3,diff=6,name="Mask of Pennance"}, {id=27791,pct=17.1,q=3,diff=6,name="Serpentcrest Life-Staff"}, {id=27795,pct=11.0,q=3,diff=6,name="Sash of Serpentra"}, {id=27787,pct=17.6,q=3,diff=6,name="Chestguard of No Remorse"} },
        sections = {
          { id=5996, title="Electrified Net", parent=0, child=0, sib=5997, order=1, spell=0, icon="Interface\\icons\\ability_ensnare", flags=0, cdisp=0,
            body="Mekgineer Steamrigger immobilizes a player in an electrified net, inflicting $35108s1 Nature damage every $35107t2 sec. for $35107d." },
          { id=5997, title="Super Shrink Ray", parent=0, child=0, sib=5998, order=2, spell=0, icon="Interface\\icons\\spell_ice_magicdamage", flags=0, cdisp=0,
            body="Mekgineer Steamrigger fires a shrink ray, reducing the damage of all players in a cone in front of him by $31485s1% for $31485d." },
          { id=5998, title="Saw Blade", parent=0, child=0, sib=5999, order=3, spell=0, icon="Interface\\icons\\inv-sword_53", flags=0, cdisp=0,
            body="Mekgineer Steamrigger fires a saw blade at a player, inflicting $31486s1 Physical damage." },
          { id=5999, title="Steamrigger Mechanics", parent=0, child=6000, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=6936,
            body="When Mekgineer Steamrigger reaches 75%, 50% and 25% remaining health, he summons Steamrigger Mechanics to repair him." },
          { id=6000, title="Repair", parent=5999, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\inv_misc_wrench_01", flags=0, cdisp=0,
            body="Steamrigger Mechanics repair Mekgineer Steamrigger, healing him for $31532s1 every $31532t1 sec." },
        },
