      { id=575, name="Warlord Kalithresh", order=3,
        uiMapID=263, x=0.7596, y=0.4365, rootSection=6001,
        desc="Deep within the Steamvault, the naga have begun experimenting with a mysterious substance to strengthen their warriors and purge them of fear. Kalithresh was one of Lady Vashj's first servants to volunteer as a test subject for this dark elixir. As reward, he has been charged with guarding the expansive Steamvault and ensuring the region's arcane machinery operates without interruption.",
        creatures = { {display=20235, file=607815, name="Warlord Kalithresh"} },
        loot = { {id=27738,pct=12.2,q=3,diff=6,name="Incanter's Pauldrons"}, {id=29243,pct=18.0,q=4,diff=6,name="Wave-Fury Vambraces"}, {id=28203,pct=11.0,q=3,diff=6,name="Breastplate of the Righteous"}, {id=27510,pct=12.4,q=3,diff=6,name="Tidefury Gauntlets"}, {id=27801,pct=10.6,q=3,diff=6,name="Beast Lord Mantle"}, {id=27799,pct=12.5,q=3,diff=6,name="Vermillion Robes of the Dominant"}, {id=27874,pct=9.6,q=3,diff=6,name="Beast Lord Leggings"}, {id=30543,pct=7.8,q=4,diff=6,name="Pontifex Kilt"}, {id=27737,pct=12.9,q=3,diff=6,name="Moonglade Shoulders"}, {id=27804,pct=12.2,q=3,diff=6,name="Devilshark Cape"}, {id=29463,pct=2.3,q=4,diff=6,name="Amber Bands of the Aggressor"}, {id=27805,pct=13.9,q=3,diff=6,name="Ring of the Silver Hand"}, {id=29351,pct=3.5,q=4,diff=6,name="Wrathtide Longbow"} },
        sections = {
