            body="Warlord Kalithresh draws power from a nearby Naga Distiller, gaining Warlord's Rage after 12 seconds if the Distiller is not destroyed." },
          { id=6002, title="Warlord's Rage", parent=6001, child=0, sib=0, order=2, spell=0, icon="Interface\\icons\\ability_bullrush", flags=0, cdisp=0,
