          { id=6004, title="Head Crack", parent=0, child=0, sib=6005, order=4, spell=0, icon="Interface\\icons\\ability_thunderbolt", flags=0, cdisp=0,
            body="Warlord Kalithresh cracks a player's head, reducing their stamina for $16172d." },
