  { id=262, name="The Underbog", isRaid=false, minLevel=60,
    mapID=546, loreFDID=608238, bgFDID=608160, buttonFDID=608199,
    desc="Coilfang Reservoir is the name for a naga-dominated compound that lurks under Zangarmarsh's deepest waters. The reservoir, punctured throughout by massive open pipes and pistons, seems big enough to house armies - and, yet, its purpose isn't strictly military.",
    encounters = {
      { id=576, name="Hungarfen", order=1,
        uiMapID=262, x=0.694, y=0.8996, rootSection=6006,
        desc="Unlike his ally, Quagmirran, the great fungal giant Hungarfen has thus far eluded enslavement by the naga. Nonetheless, he remains aggressive to all outsiders who tread into the deepest caverns of Zangarmarsh. Oblivious to the naga's machinations in other parts of the region, Hungarfen spends much of his time tending the Underspore, an ancient plant said to be his most prized possession.",
        creatures = { {display=17228, file=607649, name="Hungarfen"} },
        loot = { {id=27745,pct=13.8,q=3,diff=6,name="Hungarhide Gauntlets"}, {id=24450,pct=11.7,q=3,diff=6,name="Manaspark Gloves"}, {id=27746,pct=8.4,q=3,diff=6,name="Arcanium Signet Bands"}, {id=24451,pct=11.8,q=3,diff=6,name="Lykul Bloodbands"}, {id=27747,pct=12.8,q=3,diff=6,name="Boggspine Knuckles"}, {id=27748,pct=7.4,q=3,diff=6,name="Cassock of the Loyal"}, {id=24452,pct=12.3,q=3,diff=6,name="Starlight Gauntlets"}, {id=27743,pct=13.8,q=3,diff=6,name="Girdle of Living Flame"} },
