            body="Hungarfen summons Underbog Mushrooms at a random location that explode in a cloud of spores after 20 seconds." },
          { id=6007, title="Spore Cloud", parent=6006, child=0, sib=0, order=2, spell=0, icon="Interface\\icons\\spell_nature_dryaddispelmagic", flags=0, cdisp=0,
