      { id=577, name="Ghaz'an", order=2,
        uiMapID=262, x=0.7869, y=0.2889, rootSection=6009,
        desc="Historians have long disagreed about whether the immense hydras of Azeroth and Outland share a common ancestor. What is clear, however, is that these ruthless creatures have existed on both realms since ancient times. Ghaz'an is one of the most infamous and fearsome hydras on Outland. Under the control of Lady Vashj, this ravenous fiend has stormed the lower reaches of Zangarmarsh to terrorize the region's denizens.",
        creatures = { {display=17528, file=607614, name="Ghaz'an"} },
        loot = { {id=27760,pct=14.7,q=3,diff=6,name="Dunewind Sash"}, {id=27761,pct=18.7,q=3,diff=6,name="Ring of the Shadow Deeps"}, {id=24458,pct=14.1,q=3,diff=6,name="Studded Girdle of Virtue"}, {id=24459,pct=14.2,q=3,diff=6,name="Cloak of Healing Rays"}, {id=27755,pct=7.3,q=3,diff=6,name="Girdle of Gallantry"}, {id=24460,pct=13.0,q=3,diff=6,name="Talisman of Tenacity"}, {id=24461,pct=14.1,q=3,diff=6,name="Hatebringer"}, {id=27757,pct=16.0,q=3,diff=6,name="Greatstaff of the Leviathan"}, {id=27758,pct=12.0,q=3,diff=6,name="Hydra-fang Necklace"}, {id=24462,pct=12.8,q=3,diff=6,name="Luminous Pearls of Insight"}, {id=27759,pct=13.3,q=3,diff=6,name="Headdress of the Tides"} },
        sections = {
