      { id=578, name="Swamplord Musel'ek", order=3,
        uiMapID=262, x=0.4153, y=0.2418, rootSection=6013,
        desc="To be one of the Broken is to be an outcast. This truth weighs heavy on Swamplord Musel'ek. Although he is a member of the Murkblood Broken, he prefers to roam the caverns beneath Zangarmarsh alone. During one of these recent wanderings, he used his mastery over beasts to enthrall Windcaller Claw, a druid who had been exploring the area in the form of a ferocious bear. Musel'ek has forced Claw to act as a loyal companion who will not judge him for the twisted being he has become.",
        creatures = { {display=18570, file=607779, name="Swamplord Musel'ek"} },
        loot = { {id=27762,pct=0,q=3,diff=6,name="Weathered Band of the Swamplord"}, {id=27763,pct=20.0,q=3,diff=6,name="Crown of the Forest Lord"}, {id=27764,pct=12.1,q=3,diff=6,name="Hands of the Sun"}, {id=27765,pct=9.3,q=3,diff=6,name="Armwraps of Disdain"}, {id=24453,pct=15.2,q=3,diff=6,name="Zangartooth Shortblade"}, {id=24454,pct=17.2,q=3,diff=6,name="Cloak of Enduring Swiftness"}, {id=27766,pct=17.1,q=3,diff=6,name="Swampstone Necklace"}, {id=27767,pct=9.3,q=3,diff=6,name="Bogreaver"}, {id=24455,pct=14.5,q=3,diff=6,name="Tunic of the Nightwatcher"}, {id=24456,pct=12.4,q=3,diff=6,name="Greaves of the Iron Guardian"}, {id=24457,pct=14.4,q=3,diff=6,name="Truth Bearer Shoulderguards"} },
