      { id=579, name="The Black Stalker", order=4,
        uiMapID=262, x=0.2473, y=0.457, rootSection=6036,
        desc="The marsh walkers of Outland are towering creatures that prowl the wilds, feasting on any lesser creatures they come across. The sporelings of Zangarmarsh tell tales concerning one of these predators, a particularly ruthless beast known as the Black Stalker. Broodmother to all marsh walkers, it is said she emerges from her lair deep in the Underbog only to satisfy her hunger for delicious sporelings.",
        creatures = { {display=18194, file=607788, name="The Black Stalker"} },
