        creatures = { {display=21174, file=1378986, name="High Warlord Naj'entus"} },
        loot = { {id=32248,pct=16.0,q=4,diff=0,name="Halberd of Desolation"}, {id=32243,pct=10.0,q=4,diff=0,name="Pearl Inlaid Boots"}, {id=32239,pct=15.0,q=4,diff=0,name="Slippers of the Seacaller"}, {id=32236,pct=16.0,q=4,diff=0,name="Rising Tide"}, {id=32242,pct=6.0,q=4,diff=0,name="Boots of Oceanic Fury"}, {id=32232,pct=16.0,q=4,diff=0,name="Eternium Shell Bracers"}, {id=32377,pct=15.0,q=4,diff=0,name="Mantle of Darkness"}, {id=32237,pct=15.0,q=4,diff=0,name="The Maelstrom's Fury"}, {id=32245,pct=7.0,q=4,diff=0,name="Tide-stomper's Greaves"}, {id=32238,pct=16.0,q=4,diff=0,name="Ring of Calming Waves"}, {id=32234,pct=16.0,q=4,diff=0,name="Fists of Mukoa"}, {id=32241,pct=10.0,q=4,diff=0,name="Helm of Soothing Currents"}, {id=32247,pct=16.0,q=4,diff=0,name="Ring of Captured Storms"}, {id=32240,pct=16.0,q=4,diff=0,name="Guise of the Tidal Lurker"} },
        sections = {
          { id=15578, title="Overview", parent=0, child=15579, sib=15587, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="High Warlord Naj'entus periodically skewers players with his Impaling Spines, stunning them until freed by allies. Over the course of the encounter, Naj'entus casts Tidal Shield, becoming immune to damage and restoring health over time until a player hurls a Spine back at him to pierce the bubble." },
          { id=15579, title="Damage Dealers", parent=15578, child=0, sib=15580, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Spread out to reduce damage taken from |cFF2959D3|Hspell:39835|h[Needle Spine]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
          { id=15580, title="Healers", parent=15578, child=0, sib=15581, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Spread out to reduce damage taken from |cFF2959D3|Hspell:39835|h[Needle Spine]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
          { id=15581, title="Tanks", parent=15578, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid facing High Warlord Naj'entus at allies to avoid damage from |cFF2959D3|Hspell:39836|h[Horseshoe Swipe]|h|r.\n$bullet;Interact with Naj'entus' Spine to free a player stunned by |cFF2959D3|Hspell:39837|h[Impaling Spine]|h|r.\n$bullet;Throw Naj'entus' Spine at High Warlord Naj'entus to cancel |cFF2959D3|Hspell:39872|h[Tidal Shield]|h|r." },
