        sections = {
          { id=15599, title="Overview", parent=0, child=15600, sib=15603, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="The objective of the encounter is to assist Akama in defeating the Shade of Akama. Defeat Ashtongue Channelers and Sorcerers to allow the Shade of Akama to reach Akama, starting Stage Two. Once Stage Two begins, defeat the Shade of Akama to win the encounter before Akama is slain." },
          { id=15600, title="Damage Dealers", parent=15599, child=0, sib=15601, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;In Stage One, defeat the Ashtongue Channelers as fast as possible.\n$bullet;Defeat the Shade of Akama once he is freed." },
          { id=15601, title="Healers", parent=15599, child=0, sib=15602, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;In Stage One, defeat the Ashtongue Channelers as fast as possible.\n$bullet;Defeat the Shade of Akama once he is freed." },
          { id=15602, title="Tanks", parent=15599, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be quick to grab the attention of Ashtongue Forces as they spawn.\n$bullet;Defeat the Shade of Akama once he is freed." },
