        sections = {
          { id=15628, title="Overview", parent=0, child=15629, sib=15632, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Teron Gorefiend periodically marks a player with |cFF2959D3|Hspell:40251|h[Shadow of Death]|h|r, killing them instantly. The slain player then returns as a Vengeful Spirit, with the unique ability to hinder and destroy Shadowy Constructs that will otherwise decimate other players." },
          { id=15629, title="Damage Dealers", parent=15628, child=0, sib=15630, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be prepared to become a |cFF2959D3|Hspell:40251|h[Shadow of Death].|h|r" },
          { id=15630, title="Healers", parent=15628, child=0, sib=15631, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be prepared to become a |cFF2959D3|Hspell:40251|h[Shadow of Death].|h|r\n$bullet;Be quick to dispel |cFF2959D3|Hspell:40239|h[Incinerate]|h|r to avoid damage.\n$bullet;Targets afflicted by |cFF2959D3|Hspell:40243|h[Crushing Shadows]|h|r are especially susceptible to Shadow damage." },
          { id=15631, title="Tanks", parent=15628, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Hold the attention of Teron Gorefiend." },
