      { id=1587, name="Reliquary of Souls", order=5,
        uiMapID=342, x=0.6138, y=0.8508, rootSection=15661,
        desc="",
        creatures = { {display=21483, file=1385764, name="Essence of Suffering"}, {display=21485, file=0, name="Essence of Desire"}, {display=21484, file=0, name="Essence of Anger"} },
        loot = { {id=32363,pct=14.0,q=4,diff=0,name="Naaru-Blessed Life Rod"}, {id=32354,pct=16.0,q=4,diff=0,name="Crown of Empowered Fate"}, {id=32351,pct=8.0,q=4,diff=0,name="Elunite Empowered Bracers"}, {id=32350,pct=16.0,q=4,diff=0,name="Touch of Inspiration"}, {id=32517,pct=17.0,q=4,diff=0,name="The Wavemender's Mantle"}, {id=32349,pct=16.0,q=4,diff=0,name="Translucent Spellthread Necklace"}, {id=32362,pct=15.0,q=4,diff=0,name="Pendant of Titans"}, {id=32353,pct=17.0,q=4,diff=0,name="Gloves of Unfailing Faith"}, {id=32332,pct=17.0,q=4,diff=0,name="Torch of the Damned"}, {id=32352,pct=9.0,q=4,diff=0,name="Naturewarden's Treads"}, {id=32346,pct=16.0,q=4,diff=0,name="Boneweave Girdle"}, {id=32347,pct=16.0,q=4,diff=0,name="Grips of Damnation"}, {id=32345,pct=15.0,q=4,diff=0,name="Dreadboots of the Legion"} },
        sections = {
          { id=15661, title="Overview", parent=0, child=15662, sib=15665, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="The Reliquary of Souls manifests three different Essences over the course of the encounter, each of which applies unique effects that must be handled differently. \n\nFirst, the Essence of Suffering always strikes the nearest player and afflicts the raid with |cFF2959D3|Hspell:41292|h[Aura of Suffering]|h|r.\n\nSecond, the Essence of Desire afflicts the raid with |cFF2959D3|Hspell:41350|h[Aura of Desire]|h|r.\n\nFinally, players must defeat the Essence of Anger which afflicts the raid with |cFF2959D3|Hspell:41337|h[Aura of Anger]|h|r." },
          { id=15662, title="Damage Dealers", parent=15661, child=0, sib=15663, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid heavily damaging yourself during |cFF2959D3|Hspell:41350|h[Aura of Desire]|h|r.\n$bullet;Be aware of your threat while|cFF2959D3|Hspell:41520|h[Seethe]|h|r is active." },
          { id=15663, title="Healers", parent=15661, child=0, sib=15664, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Watch your mana during |cFF2959D3|Hspell:41292|h[Aura of Suffering]|h|r.\n$bullet;Quickly dispel |cFF2959D3|Hspell:41303|h[Soul Drain]|h|r.\n$bullet;Regenerate Mana from the Enslaved Souls during the Intermission stage." },
          { id=15664, title="Tanks", parent=15661, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;While the Essence of Desire is active, be careful of |cFF2959D3|Hspell:41410|h[Deaden]|h|r.\n$bullet;Using a Taunt effect while the Essence of Anger is active will cause |cFF2959D3|Hspell:41364|h[Seethe]|h|r.\n$bullet;Face the Essence of Anger away from allies to avoid damage from |cFF2959D3|Hspell:41545|h[Soul Scream]|h|r." },
          { id=15665, title="Stage One: Essence of Suffering", parent=0, child=15666, sib=15670, order=5, spell=0, icon=0, flags=1, cdisp=0,
            body="" },
