        sections = {
          { id=15687, title="Overview", parent=0, child=15688, sib=15691, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Mother Shahraz will link allies together with |cFF2959D3|Hspell:41001|h[Fatal Attraction]|h|r while also dealing heavy damage to the raid with her Beams." },
          { id=15688, title="Damage Dealers", parent=15687, child=0, sib=15689, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Break the demonic link of |cFF2959D3|Hspell:41001|h[Fatal Attraction]|h|r by running away from allies.\n$bullet;Avoid |cFF2959D3|Hspell: 40823|h[Interrupting Shriek]|h|r by staying away from Mother Shahraz." },
          { id=15689, title="Healers", parent=15687, child=0, sib=15690, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Tanks will take heavy damage from |cFF2959D3|Hspell:40810|h[Saber Lash]|h|r.\n$bullet;Break the demonic link of |cFF2959D3|Hspell:41001|h[Fatal Attraction]|h|r by running away from allies.\n$bullet;Avoid |cFF2959D3|Hspell: 40823|h[Interrupting Shriek]|h|r by staying away from Mother Shahraz." },
          { id=15690, title="Tanks", parent=15687, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Tanks take heavy damage from |cFF2959D3|Hspell:40810|h[Saber Lash]|h|r." },
