      { id=1589, name="The Illidari Council", order=7,
        uiMapID=345, x=0.4733, y=0.4385, rootSection=15700,
        desc="",
        creatures = { {display=21416, file=1385743, name="Gathios the Shatterer"}, {display=21417, file=0, name="High Nethermancer Zerevor"}, {display=21419, file=0, name="Lady Malande"}, {display=21418, file=0, name="Veras Darkshadow"} },
        loot = { {id=31098,pct=34.0,q=4,diff=0,name="Leggings of the Forgotten Conqueror"}, {id=32505,pct=16.0,q=4,diff=0,name="Madness of the Betrayer"}, {id=32519,pct=16.0,q=4,diff=0,name="Belt of Divine Guidance"}, {id=32373,pct=17.0,q=4,diff=0,name="Helm of the Illidari Shatterer"}, {id=32518,pct=12.0,q=4,diff=0,name="Veil of Turning Leaves"}, {id=31099,pct=34.0,q=4,diff=0,name="Leggings of the Forgotten Vanquisher"}, {id=32331,pct=16.0,q=4,diff=0,name="Cloak of the Illidari Council"}, {id=32376,pct=17.0,q=4,diff=0,name="Forest Prowler's Helm"}, {id=31100,pct=33.0,q=4,diff=0,name="Leggings of the Forgotten Protector"} },
        sections = {
          { id=15700, title="Overview", parent=0, child=15701, sib=15704, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="The Illidari Council consists of a powerful paladin, rogue, mage, and priest. They share health and bring their iconic abilities to bear against their foes." },
          { id=15701, title="Damage Dealers", parent=15700, child=0, sib=15702, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Melee damage dealers should avoid striking High Nethermancer Zerevor due to his |cFF2959D3|Hspell:41524|h[Arcane Explosion]|h|r.\n$bullet;Interrupt Lady Malande's |cFF2959D3|Hspell:41455|h[Circle of Healing]|h|r." },
          { id=15702, title="Healers", parent=15700, child=0, sib=15703, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Allies afflicted with Veras's |cFF2959D3|Hspell:41487|h[Envenom]|h|r require urgent healing attention." },
          { id=15703, title="Tanks", parent=15700, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Hold the attention of Gathios the Shatterer and Veras Darkshadow.\n$bullet;Keep Gathios the Shatterer away from the other members of the council to avoid buffing them with |cFF2959D3|Hspell:41452|h[Devotion Aura]|h|r." },
          { id=15704, title="Gathios the Shatterer", parent=0, child=15705, sib=15716, order=5, spell=0, icon=0, flags=0, cdisp=21416,
            body="" },
          { id=15705, title="Blessings", parent=15704, child=15706, sib=15711, order=6, spell=0, icon="Interface\\icons\\spell_holy_greaterblessingofkings", flags=0, cdisp=0,
            body="Gathios can have one Blessing active at a time." },
